(()=>{'use strict';const media=window.matchMedia('(prefers-reduced-motion: reduce)');const pointer=window.matchMedia('(hover: hover) and (pointer: fine)');const glow=document.querySelector('.cursor-glow'),dot=document.querySelector('.cursor-dot');if(!glow||!dot||media.matches||!pointer.matches)return;let x=-500,y=-500,gx=-500,gy=-500,active=false;const onMove=e=>{x=e.clientX;y=e.clientY;if(!active){gx=x;gy=y;active=true;document.body.classList.add('cursor-active')}dot.style.transform=`translate3d(${x-4.5}px,${y-4.5}px,0)`};window.addEventListener('pointermove',onMove,{passive:true});document.addEventListener('pointerleave',()=>{active=false;document.body.classList.remove('cursor-active')});const tick=()=>{if(media.matches||!pointer.matches){document.body.classList.remove('cursor-active');return;}if(active){gx+=(x-gx)*.13;gy+=(y-gy)*.13;glow.style.transform=`translate3d(${gx-135}px,${gy-135}px,0)`;}requestAnimationFrame(tick)};requestAnimationFrame(tick);media.addEventListener('change',()=>{if(media.matches)document.body.classList.remove('cursor-active')});})();